def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_opp = opp[-1]
    last_my = my[-1]

    if n < 8:
        return 'C'

    opp_def_rate = opp_d / n

    if last_opp == 'D':
        if n >= 2 and opp[-2] == 'D':
            if last_my == 'D':
                dd_run = 0
                for i in range(n - 1, -1, -1):
                    if my[i] == 'D' and opp[i] == 'D':
                        dd_run += 1
                    else:
                        break
                if dd_run >= 3 and opp_def_rate < 0.4:
                    if rng.random() < 0.4:
                        return 'C'
                return 'D'
            else:
                return 'D'
        else:
            if last_my == 'D':
                if opp_def_rate < 0.4:
                    if rng.random() < 0.4:
                        return 'C'
                return 'D'
            else:
                if opp_def_rate < 0.05:
                    if rng.random() < 0.9:
                        return 'C'
                elif opp_def_rate < 0.1:
                    if rng.random() < 0.7:
                        return 'C'
                elif opp_def_rate < 0.2:
                    if rng.random() < 0.3:
                        return 'C'
                return 'D'

    if last_opp == 'C':
        if last_my == 'D':
            return 'C'
        else:
            return 'C'

    return 'C'
